Settings.QueryText:
SELECT AccommodationsList.Ref AS DocRef, BEGINOFPERIOD(AccommodationsList.CheckOutDate, DAY) AS BegOfCheckOutDate, AccommodationStatuses.IsActive AS AccommodationStatusIsActive, AccommodationStatuses.IsCheckIn AS AccommodationStatusIsCheckIn, AccommodationStatuses.IsRoomChange AS AccommodationStatusIsRoomChange, AccommodationStatuses.IsInHouse AS AccommodationStatusIsInhouse, AccommodationsList.Room.SortCode AS RoomSortCode, RoomStatuses.Ref AS RoomRoomStatus, RoomStatuses.RoomStatusIcon AS RoomStatusIcon, Guests.FullName AS GuestFullName, Guests.IsInWhiteList AS GuestIsInWhiteList, Guests.IsInBlackList AS GuestIsInBlackList, Guests.MilitaryRank AS GuestMilitaryRank, Guests.Citizenship AS GuestCitizenship, Guests.Citizenship.ISOCode AS GuestCitizenshipISOCode, Guests.DateOfBirth AS GuestDateOfBirth, Guests.Age AS GuestAge, Guests.AgeRange AS GuestAgeRange, Guests.Sex AS GuestSex, Guests.IdentityDocumentSeries AS GuestIdentityDocumentSeries, Guests.IdentityDocumentNumber AS GuestIdentityDocumentNumber, Guests.Phone AS GuestPhone, Guests.EMail AS GuestEMail, ISNULL(AccommodationsList.HotelProduct.IsFolder, FALSE) AS HotelProductIsFolder, AccommodationsList.RoomRate.DefaultCheckInTime AS RoomRateDefaultCheckInTime, AccommodationsList.RoomRate.ReferenceHour AS RoomRateReferenceHour INTO AccommodationsList FROM Document.Accommodation AS AccommodationsList LEFT JOIN Catalog.Rooms AS Rooms ON AccommodationsList.Room = Rooms.Ref LEFT JOIN Catalog.AccommodationStatuses AS AccommodationStatuses ON AccommodationsList.AccommodationStatus = AccommodationStatuses.Ref LEFT JOIN Catalog.RoomStatuses AS RoomStatuses ON (Rooms.RoomStatus = RoomStatuses.Ref) LEFT JOIN Catalog.Clients AS Guests ON AccommodationsList.Guest = Guests.Ref WHERE AccommodationsList.Posted AND &qGenerateList AND AccommodationsList.AccommodationStatus.IsActive AND AccommodationsList.AccommodationStatus.IsInHouse AND AccommodationsList.Hotel = &qHotel ;
//////////////////////////////////////////////////////////////////////////////// SELECT ExpectedRoomMovesRows.Ref AS Ref, ExpectedRoomMovesRows.Room AS Room, BEGINOFPERIOD(ExpectedRoomMovesRows.AccountingDate, DAY) AS AccountingDate INTO ExpectedRoomMoves FROM Document.Accommodation.RoomRates AS ExpectedRoomMovesRows INNER JOIN AccommodationsList AS AccommodationsList ON ExpectedRoomMovesRows.Ref = AccommodationsList.DocRef WHERE ExpectedRoomMovesRows.Room <> VALUE(Catalog.Rooms.EmptyRef)
GROUP BY ExpectedRoomMovesRows.Ref, BEGINOFPERIOD(ExpectedRoomMovesRows.AccountingDate, DAY), ExpectedRoomMovesRows.Room ;
//////////////////////////////////////////////////////////////////////////////// SELECT Accommodations.RoomType AS RoomType, Accommodations.RoomType.Code AS RoomTypeCode, Accommodations.GuestGroup AS GuestGroup, Accommodations.GuestGroup.Code AS GuestGroupCode, Accommodations.GuestGroup.ColorHexString AS GuestGroupColorHexString, Accommodations.Customer AS Customer, ISNULL(Accommodations.Customer.ColorHexString, "") AS CustomerColorHexString, Accommodations.Contract AS Contract, ISNULL(Accommodations.Contract.ColorHexString, "") AS ContractColorHexString, Accommodations.Agent AS Agent, ISNULL(Accommodations.Agent.ColorHexString, "") AS AgentColorHexString, Accommodations.NumberOfPersons AS NumberOfPersons, Accommodations.SourceOfBusiness.Code AS SourceOfBusinessCode, Accommodations.SourceOfBusiness AS SourceOfBusiness, Accommodations.MarketingCode.Code AS MarketingCodeCode, Accommodations.MarketingCode AS MarketingCode, Accommodations.ClientType AS ClientType, Accommodations.ClientType.Code AS ClientTypeCode, ISNULL(Accommodations.ClientType.ColorHexString, "") AS ClientTypeColorHexString, DiscountTypes.Ref AS DiscountCardDiscountType, ISNULL(DiscountTypes.ColorHexString, "") AS DiscountCardDiscountTypeColorHexString, Accommodations.Guest AS Guest, AccommodationsList.GuestFullName AS GuestFullName, AccommodationsList.GuestIsInWhiteList AS VIP, AccommodationsList.GuestMilitaryRank AS Rank, AccommodationsList.GuestCitizenshipISOCode AS GuestCitizenshipISOCode, AccommodationsList.GuestDateOfBirth AS GuestDateOfBirth, CASE WHEN ISNULL(AccommodationsList.GuestDateOfBirth, DATETIME(1, 1, 1)) > DATETIME(1, 1, 1) THEN CASE WHEN YEAR(Accommodations.CheckInDate) = YEAR(Accommodations.CheckOutDate) THEN CASE WHEN MONTH(AccommodationsList.GuestDateOfBirth) * 100 + DAY(AccommodationsList.GuestDateOfBirth) >= MONTH(Accommodations.CheckInDate) * 100 + DAY(Accommodations.CheckInDate) AND MONTH(AccommodationsList.GuestDateOfBirth) * 100 + DAY(AccommodationsList.GuestDateOfBirth) <= MONTH(Accommodations.CheckOutDate) * 100 + DAY(Accommodations.CheckOutDate) THEN 55 ELSE 0 END ELSE CASE WHEN MONTH(AccommodationsList.GuestDateOfBirth) * 100 + DAY(AccommodationsList.GuestDateOfBirth) >= MONTH(Accommodations.CheckInDate) * 100 + DAY(Accommodations.CheckInDate) AND MONTH(AccommodationsList.GuestDateOfBirth) * 100 + DAY(AccommodationsList.GuestDateOfBirth) <= 1231 THEN 55 WHEN MONTH(AccommodationsList.GuestDateOfBirth) * 100 + DAY(AccommodationsList.GuestDateOfBirth) <= MONTH(Accommodations.CheckOutDate) * 100 + DAY(Accommodations.CheckOutDate) AND MONTH(AccommodationsList.GuestDateOfBirth) * 100 + DAY(AccommodationsList.GuestDateOfBirth) >= 101 THEN 55 ELSE 0 END END ELSE 0 END AS BirthDateIcon, AccommodationsList.GuestAge AS GuestAge, AccommodationsList.GuestAgeRange AS GuestAgeRange, CASE WHEN AccommodationsList.GuestSex = VALUE(Enum.Sex.Male) THEN 26 WHEN AccommodationsList.GuestSex = VALUE(Enum.Sex.Female) THEN 27 ELSE 0 END AS GuestSexIcon, CASE WHEN Accommodations.Phone <> "" THEN Accommodations.Phone ELSE AccommodationsList.GuestPhone END AS Phone, CASE WHEN Accommodations.EMail <> "" THEN Accommodations.EMail ELSE AccommodationsList.GuestEMail END AS EMail, AccommodationsList.GuestIdentityDocumentSeries AS GuestPassportSeries, AccommodationsList.GuestIdentityDocumentNumber AS GuestPassportNumber, Accommodations.AccommodationType AS AccommodationType, CASE WHEN AccommodationsList.HotelProductIsFolder THEN UNDEFINED ELSE Accommodations.HotelProduct END AS Vaucher, Accommodations.CheckInDate AS CheckInDate, Accommodations.Duration AS Duration, Accommodations.CheckOutDate AS CheckOutDate, BEGINOFPERIOD(Accommodations.CheckInDate, DAY) AS BegOfCheckInDate, BEGINOFPERIOD(Accommodations.CheckOutDate, DAY) AS BegOfCheckOutDate, CASE WHEN AccommodationsList.RoomRateDefaultCheckInTime <> DATETIME(1, 1, 1) AND HOUR(Accommodations.CheckInDate) * 100 + MINUTE(Accommodations.CheckInDate) = HOUR(AccommodationsList.RoomRateDefaultCheckInTime) * 100 + MINUTE(AccommodationsList.RoomRateDefaultCheckInTime) THEN TRUE WHEN AccommodationsList.RoomRateReferenceHour <> DATETIME(1, 1, 1) AND AccommodationsList.RoomRateDefaultCheckInTime = DATETIME(1, 1, 1) AND HOUR(Accommodations.CheckInDate) * 100 + MINUTE(Accommodations.CheckInDate) = HOUR(AccommodationsList.RoomRateReferenceHour) * 100 + MINUTE(AccommodationsList.RoomRateReferenceHour) THEN TRUE ELSE FALSE END AS IsDefaultCheckInTime, CASE WHEN AccommodationsList.RoomRateReferenceHour <> DATETIME(1, 1, 1) AND HOUR(Accommodations.CheckOutDate) * 100 + MINUTE(Accommodations.CheckOutDate) = HOUR(AccommodationsList.RoomRateReferenceHour) * 100 + MINUTE(AccommodationsList.RoomRateReferenceHour) THEN TRUE ELSE FALSE END AS IsDefaultCheckOutTime, CAST(Accommodations.Remarks AS STRING(512)) AS Remarks, CAST(Accommodations.HousekeepingRemarks AS STRING(512)) AS HousekeepingRemarks, CAST(Accommodations.Car AS STRING(512)) AS Car, Accommodations.PlannedPaymentMethod.Code AS PaymentMethod, Accommodations.Room AS Room, AccommodationsList.RoomRoomStatus AS RoomRoomStatus, CASE WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.None) THEN 5 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Reserved) THEN 6 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Occupied) THEN 2 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.OccupiedDirty) THEN 7 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Repair) THEN 8 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Luggage) THEN 9 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Malfunction) THEN 10 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Waiting) THEN 1 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.TidyingUp) THEN 0 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.CheckOut) THEN 3 WHEN AccommodationsList.RoomStatusIcon = VALUE(Enum.RoomStatusesIcons.Vacant) THEN 4 ELSE 5 END AS RoomStatusIcon, CASE WHEN AccommodationsList.AccommodationStatusIsActive THEN CASE WHEN AccommodationsList.AccommodationStatusIsCheckIn AND AccommodationsList.AccommodationStatusIsInhouse THEN 41 WHEN AccommodationsList.AccommodationStatusIsRoomChange AND AccommodationsList.AccommodationStatusIsInhouse THEN 39 ELSE 40 END ELSE 43 END AS IndexRoomStatuses, Accommodations.GuaranteeType AS GuaranteeType, Accommodations.GuaranteeType.Code AS GuaranteeTypeCode, ExpectedRoomMoves.Room AS RoomTo, Accommodations.AccommodationType.SortCode AS AccommodationTypeSortCode, AccommodationsList.RoomSortCode AS RoomSortCode, Accommodations.AccommodationStatus AS AccommodationStatus, Accommodations.AccommodationType.Type AS AccommodationTypeType, Accommodations.Ref AS Ref, Accommodations.Number AS RefNumber, Accommodations.RoomRate AS RoomRate, Accommodations.ServicePackage AS ServicePackage, Accommodations.RoomQuota AS RoomQuota, ISNULL(Accommodations.RoomQuota.ColorHexString, "") AS RoomQuotaColorHexString, CAST(Accommodations.RoomPropertiesCodes AS STRING(512)) AS RoomPropertiesCodes, CAST(Accommodations.RoomPropertiesDescriptions AS STRING(512)) AS RoomPropertiesDescriptions, 0 AS ClientSumBalance, 0 AS ClientLimitBalance, 0 AS CustomerSumBalance, Accommodations.ReportingCurrency AS FolioCurrency, Accommodations.AccommodationTemplate AS AccommodationTemplate, Accommodations.NumberOfAdults AS NumberOfAdults, Accommodations.NumberOfTeenagers AS NumberOfTeenagers, Accommodations.NumberOfChildren AS NumberOfChildren, Accommodations.NumberOfInfants AS NumberOfInfants, Accommodations.Number AS DocNumber, Accommodations.Author AS Author, Accommodations.Posted AS Posted, Accommodations.DeletionMark AS DeletionMark, Accommodations.SortCode AS SortCode, &qShowAllGuests AS ShowAllGuests, &qBalancesAreVisible AS BalancesAreVisible, CASE WHEN GuestsExportedToUMMS.CaseUUID IS NULL THEN FALSE ELSE TRUE END AS GuestWasExportedToUMMS FROM Document.Accommodation AS Accommodations INNER JOIN AccommodationsList AS AccommodationsList ON Accommodations.Ref = AccommodationsList.DocRef LEFT JOIN Catalog.DiscountTypes AS DiscountTypes ON Accommodations.DiscountCard.DiscountType = DiscountTypes.Ref LEFT JOIN ExpectedRoomMoves AS ExpectedRoomMoves ON Accommodations.Ref = ExpectedRoomMoves.Ref AND (ExpectedRoomMoves.Room <> Accommodations.Room) AND (ExpectedRoomMoves.AccountingDate = &qAccountingDate) LEFT JOIN InformationRegister.GuestsExportedToUMMS AS GuestsExportedToUMMS ON Accommodations.Guest = GuestsExportedToUMMS.Guest AND Accommodations.Hotel = GuestsExportedToUMMS.Hotel AND (AccommodationsList.BegOfCheckOutDate = GuestsExportedToUMMS.CheckOutDate) WHERE (NOT &qShowExpectedRoomMovesOnly OR &qShowExpectedRoomMovesOnly AND NOT ExpectedRoomMoves.Room IS NULL)
